{
  "findings": [
    {
      "check_id": "CKV_AZURE_109",
      "title": "Role assignment at subscription scope without condition",
      "resource": "azurerm_role_assignment.negative8",
      "severity": "HIGH",
      "explanation": "The role assignment grants permissions at the broad subscription scope. While a 'condition_version' is specified, no actual 'condition' block or string is provided to restrict the actions or resources accessible by this principal, effectively granting full subscription-level access defined by the role."
    }
  ],
  "patched_code": "resource \"azurerm_role_assignment\" \"negative8\" {\n  role_definition_id   = \"18d7d88d-d35e-4fb5-a5c3-7773c20a72d9\"\n  scope                = \"/subscriptions/12345678-1234-1234-1234-123456789abc\"\n  principal_id         = data.azurerm_client_config.current.object_id\n  principal_type       = \"ServicePrincipal\"\n  condition_version    = \"2.0\"\n  # TODO: Add a specific 'condition' attribute to restrict actions/resources.\n  # Example: condition = \"(ActionMatches{'Microsoft.Storage/storageAccounts/blobServices/containers/blobs/read'}) AND (ResourceMatches{'/subscriptions/12345678-1234-1234-1234-123456789abc/resourceGroups/my-resource-group/providers/Microsoft.Storage/storageAccounts/my-storage-account/blobServices/default/containers/my-container/*'})\"\n}\n",
  "fix_summary": "Added a TODO comment and placeholder structure indicating that a valid 'condition' attribute must be supplied to restrict the subscription-scoped role assignment, as defining only 'condition_version' without a condition does not enforce least privilege."
}
